local PrivateServerHttpService = game:GetService("HttpService")
local PrivateServerTeleportService = game:GetService("TeleportService")

local PrivateServer = {
    Status = "Pick a max player count, then Hop Server Now.",
    HopFailed = false,
    LastHopAt = 0,
    AutoRunning = false,
    AutoGeneration = 0,
}

local function PrivateServerSetStatus(Message)
    PrivateServer.Status = tostring(Message or "")
    _G.PrivateServerStatus = PrivateServer.Status
    GlobalEnv.PrivateServerStatus = PrivateServer.Status
end

local function PrivateServerNormalizeMax(Value)
    if type(Value) == "table" then
        Value = Value[1]
    end

    local Number = tonumber(tostring(Value or "2"):match("%d+")) or 2
    Number = math.clamp(math.floor(Number), 1, 5)
    return tostring(Number)
end

local function PrivateServerSetMaxPlayers(Value)
    local Normalized = PrivateServerNormalizeMax(Value)
    _G.PrivateServerMaxPlayers = Normalized
    GlobalEnv.PrivateServerMaxPlayers = Normalized
    return tonumber(Normalized) or 2
end

local function PrivateServerGetMaxPlayers()
    local Value = _G.PrivateServerMaxPlayers
    if Value == nil then
        Value = GlobalEnv.PrivateServerMaxPlayers
    end
    return PrivateServerSetMaxPlayers(Value or "2")
end

-- Respect active stealing/delivery activity before hopping servers.
local function PrivateServerHubBusy()
    if ProcessingSteal == true or ProcessingAutoEgg == true then
        return true
    end

    if type(ClTP) == "table" and type(ClTP.State) == "table" then
        if ClTP.State.Busy == true then
            return true
        end
    end

    local EggRuntime = GlobalEnv.__SenaV4EggRuntime or _G.__SenaV4EggRuntime
    if EggRuntime and (EggRuntime.running or EggRuntime.travelBusy
        or (EggRuntime.carry and EggRuntime.carry.active)) then
        return true
    end

    local PlayerStealRuntime = GlobalEnv.__SenaV4PlayerSteal or _G.__SenaV4PlayerSteal
    if PlayerStealRuntime and PlayerStealRuntime.running then
        return true
    end

    return false
end

local function PrivateServerCollectServers(MaxPlaying)
    local Servers = {}
    local Cursor = ""

    -- Inspect up to three pages, matching Sena Hub's server search behavior.
    for _ = 1, 3 do
        local OK, Result = pcall(function()
            local URL = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100&excludeFullGames=true"):format(game.PlaceId)
            if Cursor ~= "" then
                URL = URL .. "&cursor=" .. Cursor
            end
            return PrivateServerHttpService:JSONDecode(game:HttpGet(URL))
        end)

        if not OK or type(Result) ~= "table" then
            break
        end

        for _, Server in ipairs(Result.data or {}) do
            local Playing = tonumber(Server.playing)
            local MaxPlayers = tonumber(Server.maxPlayers)
            local ServerId = tostring(Server.id or "")

            if ServerId ~= ""
                and ServerId ~= game.JobId
                and Playing
                and MaxPlayers
                and Playing < MaxPlayers
                and (MaxPlaying == nil or Playing <= MaxPlaying) then
                Servers[#Servers + 1] = {
                    id = ServerId,
                    playing = Playing,
                }
            end
        end

        Cursor = Result.nextPageCursor or ""
        if Cursor == "" then
            break
        end
    end

    table.sort(Servers, function(A, B)
        return A.playing < B.playing
    end)

    return Servers
end

local function PrivateServerHopToList(Servers)
    if type(Servers) ~= "table" or #Servers == 0 then
        return false
    end

    for _, Server in ipairs(Servers) do
        PrivateServer.HopFailed = false

        local Started = pcall(function()
            PrivateServerTeleportService:TeleportToPlaceInstance(
                game.PlaceId,
                Server.id,
                Player
            )
        end)

        if Started then
            local StartedAt = os.clock()
            while not PrivateServer.HopFailed and os.clock() - StartedAt < 6 do
                task.wait(0.25)
            end

            if not PrivateServer.HopFailed then
                return true
            end
        end

        task.wait(0.3)
    end

    return false
end

local function PrivateServerFindTargets()
    local MaxPlayers = PrivateServerGetMaxPlayers()
    local Servers = PrivateServerCollectServers(nil)

    if #Servers == 0 then
        return nil
    end

    local Candidates = {}
    for _, Server in ipairs(Servers) do
        if Server.playing + 1 <= MaxPlayers then
            Candidates[#Candidates + 1] = Server
        end
    end

    -- If no server meets the chosen limit, try the least-populated servers.
    if #Candidates == 0 then
        local LowestCount = Servers[1].playing
        for _, Server in ipairs(Servers) do
            if Server.playing == LowestCount then
                Candidates[#Candidates + 1] = Server
            end
        end
    end

    local Targets = {}
    while #Candidates > 0 and #Targets < 5 do
        Targets[#Targets + 1] = table.remove(Candidates, math.random(1, #Candidates))
    end

    return Targets
end

local function PrivateServerHopOnce()
    local MaxPlayers = PrivateServerGetMaxPlayers()
    local CurrentPlayerCount = #Players:GetPlayers()

    if CurrentPlayerCount <= MaxPlayers then
        PrivateServerSetStatus(
            "This server is good (" .. CurrentPlayerCount
                .. " player(s), max " .. MaxPlayers .. ")."
        )
        return false
    end

    if PrivateServerHubBusy() then
        PrivateServerSetStatus("Waiting until you finish stealing...")
        return false
    end

    PrivateServerSetStatus("Searching for a quieter server...")
    local Targets = PrivateServerFindTargets()

    if not Targets or #Targets == 0 then
        PrivateServerSetStatus("Could not load the server list. Try again.")
        return false
    end

    PrivateServerSetStatus("Teleporting...")
    PrivateServer.LastHopAt = os.clock()

    if PrivateServerHopToList(Targets) then
        return true
    end

    PrivateServerSetStatus("Teleport failed. Trying again soon.")
    return false
end

local function PrivateServerStartAutoHop()
    if PrivateServer.AutoRunning then
        return
    end

    PrivateServer.AutoRunning = true
    PrivateServer.AutoGeneration = PrivateServer.AutoGeneration + 1
    local Generation = PrivateServer.AutoGeneration

    task.spawn(function()
        while Generation == PrivateServer.AutoGeneration
            and _G.PrivateServerAutoHop == true do
            local MaxPlayers = PrivateServerGetMaxPlayers()

            if #Players:GetPlayers() <= MaxPlayers then
                PrivateServerSetStatus("Good server found. Waiting...")
                local Waited = 0
                while Waited < 3
                    and Generation == PrivateServer.AutoGeneration
                    and _G.PrivateServerAutoHop == true do
                    task.wait(0.2)
                    Waited = Waited + 0.2
                end
            else
                PrivateServerHopOnce()
                local Waited = 0
                while Waited < 5
                    and Generation == PrivateServer.AutoGeneration
                    and _G.PrivateServerAutoHop == true do
                    task.wait(0.2)
                    Waited = Waited + 0.2
                end
            end
        end

        if Generation == PrivateServer.AutoGeneration then
            PrivateServer.AutoRunning = false
            if _G.PrivateServerAutoHop ~= true then
                PrivateServerSetStatus("Auto hop stopped.")
            end
        end
    end)
end

local function PrivateServerStopAutoHop()
    PrivateServer.AutoGeneration = PrivateServer.AutoGeneration + 1
    PrivateServer.AutoRunning = false
    if _G.PrivateServerAutoHop ~= true then
        PrivateServerSetStatus("Auto hop stopped.")
    end
end

local function PrivateServerSetAutoHop(Value)
    local Enabled = Value == true
    _G.PrivateServerAutoHop = Enabled
    GlobalEnv.PrivateServerAutoHop = Enabled

    if Enabled then
        PrivateServerStartAutoHop()
    else
        PrivateServerStopAutoHop()
    end
end

-- Keep the teleport-failure signal so failed attempts can move to the next ID.
pcall(function()
    PrivateServerTeleportService.TeleportInitFailed:Connect(function(FailedPlayer)
        if FailedPlayer == Player then
            PrivateServer.HopFailed = true
        end
    end)
end)

-- Export the controls/helpers for use by other scripts through _G.
PrivateServerSetMaxPlayers(
    _G.PrivateServerMaxPlayers or GlobalEnv.PrivateServerMaxPlayers or "2"
)
local InitialAutoHop = _G.PrivateServerAutoHop
if InitialAutoHop == nil then
    InitialAutoHop = GlobalEnv.PrivateServerAutoHop
end
_G.PrivateServerAutoHop = InitialAutoHop == true
GlobalEnv.PrivateServerAutoHop = _G.PrivateServerAutoHop

_G.SetPrivateServerMaxPlayers = PrivateServerSetMaxPlayers
_G.GetPrivateServerMaxPlayers = PrivateServerGetMaxPlayers
_G.SetPrivateServerAutoHop = PrivateServerSetAutoHop
_G.StartPrivateServerAutoHop = PrivateServerStartAutoHop
_G.StopPrivateServerAutoHop = function()
    PrivateServerSetAutoHop(false)
end
_G.HopPrivateServerNow = PrivateServerHopOnce
_G.CollectPrivateServers = PrivateServerCollectServers
_G.FindPrivateServerTargets = PrivateServerFindTargets
_G.HopToPrivateServerList = PrivateServerHopToList
_G.GetPrivateServerStatus = function()
    return PrivateServer.Status
end
_G.PrivateServerTabState = PrivateServer

GlobalEnv.SetPrivateServerMaxPlayers = _G.SetPrivateServerMaxPlayers
GlobalEnv.GetPrivateServerMaxPlayers = _G.GetPrivateServerMaxPlayers
GlobalEnv.SetPrivateServerAutoHop = _G.SetPrivateServerAutoHop
GlobalEnv.StartPrivateServerAutoHop = _G.StartPrivateServerAutoHop
GlobalEnv.StopPrivateServerAutoHop = _G.StopPrivateServerAutoHop
GlobalEnv.HopPrivateServerNow = _G.HopPrivateServerNow
GlobalEnv.CollectPrivateServers = _G.CollectPrivateServers
GlobalEnv.FindPrivateServerTargets = _G.FindPrivateServerTargets
GlobalEnv.HopToPrivateServerList = _G.HopToPrivateServerList
GlobalEnv.GetPrivateServerStatus = _G.GetPrivateServerStatus
GlobalEnv.PrivateServerTabState = PrivateServer
